70	// Compile-time guard: the byte budget the launcher uses (kMambaSmemBytes) MUST
71	// equal sizeof(MambaSampleSmem). model_stage_mamba3.cuh already static_asserts
72	// the same equality (it pins kMambaSmemFloats to the actual struct); we restate
73	// it here so this header is self-contained and a drift fails loudly at this TU.
