78	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor slice
79	// at `off` within the flat [m|v|extra] layout. Per-TENSOR fields and all scalars
80	// pass through unchanged. (Identical to the decoder's rebase_state; redefined here
81	// under a mamba_ name so this header stays self-contained — the decoder file is
82	// owned by a sibling agent and must not be included.)
83	template <OptId Opt>
84	__device__ __forceinline__ FusedOptState
85	mamba_rebase_state(const FusedOptState& s, int64_t off) {
86	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
87	    if (t.exp_avg)    t.exp_avg    += off;
88	    if (t.exp_avg_sq) t.exp_avg_sq += off;
89	    if (t.ema)        t.ema        += off;
90	    if (t.sam_dir)    t.sam_dir    += off;
91	    if (t.s_track)    t.s_track    += off;
92	    if (t.mu)         t.mu         += off;
93	    if (t.orth)       t.orth       += off;
94	    if (t.smart_grad) t.smart_grad += off;
95	    return t;
96	}
