98	// The L3-REAL Mamba megakernel needs the int TOKEN path + a grad-partial
99	// workspace. Kept a SEPARATE kernel + launcher (not folded into the surrogate
100	// fused_megakernel) so the surrogate path is untouched. MambaTokenCtx mirrors the
101	// decoder's DecoderTokenCtx (int tokens, NOT ViT's float patches).
102	//
103	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
104	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
105	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
106	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
107	// total == kMambaTotalElems == 259425.
108	struct MambaTokenCtx {
109	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
110	    const int* targets;  // [B]       int32 target ids in [0, kPHead)
111	    int        B;        // batch size
112	    float*     workspace; // grad partials + loss partials + reduced loss
113	    float*     loss_out;  // device float the kernel writes the mean loss into
114	};
115	
116	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
117	//    threads/CTA. MambaSampleSmem (~141.72 KB) lives in DYNAMIC smem (extern). ──
118	// sizes/offsets are NOT host-passed: per-tensor numel/offset live in the
119	// __constant__ tables kMambaSizes/kMambaOffsets (mamba3_layout.cuh), read directly
120	// by the reduce + optimizer phases.
121	template <OptId Opt>
122	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
123	fused_mamba_megakernel(PersistentContext ctx,
124	                       float* __restrict__ params,
125	                       MambaTokenCtx tok,
126	                       float* __restrict__ grad,        // reduced grad [total]
127	                       float lr, int step, FusedOptState st) {
128	    extern __shared__ char mamba_smem_raw[];
129	    MambaSampleSmem& sm = *reinterpret_cast<MambaSampleSmem*>(mamba_smem_raw);
130	    GridBarrier bar = ctx.barrier();
131	    const int cta = blockIdx.x;
132	    const int nCTA = (int)ctx.n_ctas;
133	    const int64_t total = kMambaTotalElems;
134	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
135	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
136	
137	    // NO warp-group register repartition here (UNLIKE the decoder/vit seams).
138	    // The decoder/vit copy a §3.4 producer/consumer setmaxnreg (dealloc<32> on
139	    // warpgroup 0, alloc<200> on warpgroup 1) — valid ONLY when warpgroup 0 needs
140	    // few registers. Mamba is NOT warp-specialized that way: ALL 256 threads do
141	    // SYMMETRIC selective-scan work, each thread owning a channel j∈[0,256) and
142	    // holding large register-resident scan state (fwd A[16]+h[16]; bwd adds
143	    // hh[kSeq+1][kState]+a_save[kSeq][kState]+dB_loc/dC_loc[kSeq][kState]+gh+dA),
144	    // so a dealloc<32> would spill it. __launch_bounds__(SG_TUNED_MEGA_BLOCK) sets the uniform
145	    // budget; the compiler allocates symmetrically across all 256 threads.
146	
147	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
148	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
149	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
150	    bar.sync();   // B0
151	
152	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
153	    MambaWeights w = mb_bind(params);
154	    MambaGrad g = mb_bind_grad(my_partial);
155	    const int B = tok.B;
156	    const int base = B / nCTA, rem = B % nCTA;
157	    const int b0 = cta * base + (cta < rem ? cta : rem);
158	    const int cnt = base + (cta < rem ? 1 : 0);
159	    const int b1 = b0 + cnt;
160	    __shared__ int tok_s[mb::kSeq];   // this sample's token ids (broadcast)
161	    __shared__ int tgt_s;
162	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
163	    for (int b = b0; b < b1; ++b) {
164	        if (threadIdx.x < mb::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * mb::kSeq + threadIdx.x];
165	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
166	        __syncthreads();
167	        float nll = mb_forward_sample(w, tok_s, tgt_s, &sm);
168	        mb_backward_sample(w, g, tok_s, tgt_s, B, &sm);
169	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
170	        __syncthreads();   // sample boundary: all grad writes done before reuse
171	    }
172	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
173	    bar.sync();   // B1: all CTA partials + loss slots complete
174	
175	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
176	    //    (one task = one parameter tensor; sum its elements across CTAs in
177	    //    ascending CTA index). Summation ORDER (ascending cta) is fixed →
178	    //    deterministic regardless of which CTA grabs the task. ─────────────────
179	    {
180	        __shared__ int task_slot;
181	        TaskQueue q = ctx.queue();
182	        for (int t = q.next_block(&task_slot); t < kMambaNumTensors;
183	             t = q.next_block(&task_slot)) {
184	            const int n = kMambaSizes[t];
185	            const int64_t off = (int64_t)kMambaOffsets[t];
186	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
187	                float acc = 0.0f;
188	                for (int c = 0; c < nCTA; ++c)
189	                    acc += tok.workspace[(int64_t)c * total + off + i];
190	                grad[off + i] = acc;
191	            }
192	        }
193	    }
194	    // Loss reduction (fp64 ordered) by CTA 0 only — the loss rel-tol is the
195	    // tightest gate; fp32 atomic-summing many terms can miss it.
196	    if (cta == 0 && threadIdx.x == 0) {
197	        double s = 0.0;
198	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
199	        float mean = (float)(s / (double)B);
200	        *tok.loss_out = mean;
201	    }
202	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
203	
204	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 28
205	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
206	    st.lr = lr;
207	    {
208	        __shared__ int task_slot;
209	        TaskQueue q = ctx.queue();
210	        for (int t = q.next_block(&task_slot); t < kMambaNumTensors;
211	             t = q.next_block(&task_slot)) {
212	            const int n = kMambaSizes[t];
213	            const int64_t off = (int64_t)kMambaOffsets[t];
214	            const FusedOptState ts = mamba_rebase_state<Opt>(st, off);
215	            float* __restrict__ p = params + off;
216	            const float* __restrict__ gg = grad + off;
217	            for (int i = threadIdx.x; i < n; i += blockDim.x)
218	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
219	        }
220	    }
221	}
