223	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
224	//    Mirrors launch_fused_decoder_megakernel's hang-freedom contract (occupancy≥1
225	//    or refuse), PLUS the DYNAMIC-SMEM opt-in that the Mamba footprint requires
226	//    (exactly as launch_fused_vit_megakernel does):
227	//      (1) cudaFuncSetAttribute(MaxDynamicSharedMemorySize, kMambaSmemBytes)
228	//      (2) dynamicSMemBytes = kMambaSmemBytes in the occ≥1 query
229	//      (3) dynamicSMemBytes = kMambaSmemBytes at <<<...>>>
230	//    All three are mandatory; missing any one makes the launch silently fail. ───
231	template <OptId Opt>
232	cudaError_t launch_fused_mamba_megakernel(
233	        PersistentContext ctx, float* params, MambaTokenCtx tok,
234	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
235	    int dev = 0;
236	    cudaError_t err = cudaGetDevice(&dev);
237	    if (err != cudaSuccess) return err;
238	    int n_sms = 0;
239	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
240	    if (err != cudaSuccess) return err;
241	
242	    const int dyn_smem = (int)kMambaSmemBytes;   // 145124 B (≈141.72 KB)
243	
244	    // (1) Opt in to >48 KB dynamic smem for THIS kernel. Without this the launch
245	    //     fails with cudaErrorInvalidValue (the static 48 KB default applies).
246	    err = cudaFuncSetAttribute(
247	        (const void*)&fused_mamba_megakernel<Opt>,
248	        cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
249	    if (err != cudaSuccess) return err;
250	
251	    // (2) Occupancy with the REAL dynamic-smem request (hang-freedom is honest).
252	    int occ = 0;
253	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
254	        &occ, (const void*)&fused_mamba_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
255	        /*dynamicSMemBytes=*/dyn_smem);
256	    if (err != cudaSuccess) return err;
257	    // At least one CTA per SM must be resident or the grid barrier can never be
258	    // satisfied. ~141.72 KB dynamic smem fits the sm_90 ~227 KB cap at occ=1 (the
259	    // persistent megakernel is one-CTA-per-SM by design); if it cannot place one
260	    // block/SM, REFUSE rather than hang.
261	    assert(occ >= 1 &&
262	           "fused_mamba_megakernel: 0 blocks/SM — GridBarrier would hang. The "
263	           "Mamba per-sample smem (~142KB dynamic) + regs exceed one-block-per-SM "
264	           "occupancy on this device; reduce footprint or fall back to eager.");
265	    if (occ < 1) return cudaErrorLaunchOutOfResources;
266	
267	    const unsigned launch_ctas = (unsigned)n_sms;
268	    ctx.n_ctas = launch_ctas;
269	
270	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
271	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
272	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
273	
274	    // (3) Launch WITH the dynamic-smem byte count.
275	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
276	    fused_mamba_megakernel<Opt><<<grid, block, dyn_smem, stream>>>(
277	        ctx, params, tok, grad, lr, step, st);
278	    return cudaGetLastError();
279	}
