803	// ════════════════════════════════════════════════════════════════════════
804	//  BACKWARD over one TOKEN TILE. Assumes dectc_forward_tile ran for THIS tile
805	//  (scratch + DecActs X-inputs populated). Fork B: computes dX via wgmma and
806	//  WRITES the dY output-adjoints to DecActs (dY_qkv/dY_a/dY_ff0/dY_ff2/
807	//  dY_logits) + dh0 for P2's output-stationary dW — it does NOT touch the
808	//  weight dW here. ACCUMULATES the 10 LN-vector grads (γ/β) into the per-CTA
809	//  LN-vec partials `lnvec` [kNumLnVec × d] (deterministic single-owner-per-j).
810	//  `B` is the full batch (CE mean scale). Mirrors dec_backward_sample.
811	//
812	//  dqkv/dctx/dgact intermediates use the fp32 `work` buffer + a second fp32
813	//  buffer `work2` (caller passes both, each [nrows×dff]); dh (running adjoint)
814	//  is the dedicated scratch.dh.
815	// ════════════════════════════════════════════════════════════════════════
816	__device__ void dectc_backward_tile(
817	        const DecWeights& w, int g0, int nrows, int B, const DecActs& acts,
818	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
819	        float* __restrict__ lnvec, float* __restrict__ work2,
820	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
821	    const int nsamp = nrows / dec::kSeq;
822	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
823	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
824	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
825	    for (int li = 0; li < dec::kLayers; ++li) {
826	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
827	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
828	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
829	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
830	    }
831	    float* gn_normw = lnvec + (int64_t)8 * dec::kD;
832	    float* gn_normb = lnvec + (int64_t)9 * dec::kD;
833	
834	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B, overwrite logits.
835	    //    head bwd: dY_logits[si] = dlogits (the head dW operand); dhn = dlogits@out_w.
836	    //    final-norm bwd: dh_last (last position only) → scratch.dh (zero others). ──
837	    // First zero scratch.dh for the whole tile (only last positions get grad).
838	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
839	    __syncthreads();
840	    for (int si = 0; si < nsamp; ++si) {
841	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
842	        const int gs = si_global(g0, si);
843	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
844	        int tgt = tgt_ids[gs];
845	        // softmax of cached logits.
846	        float lmax = -CUDART_INF_F;
847	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
848	        lmax = dec_block_max(lmax, red);
849	        float es = 0.0f;
850	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
851	        es = dec_block_sum(es, red);
852	        float inv_es = 1.0f / es;
853	        // dlogits → overwrite lg, AND write to dY_logits[gs] (bf16, head dW operand).
854	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
855	            float smo = __expf(lg[o] - lmax) * inv_es;
856	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
857	            lg[o] = dl;
858	            acts.dY_logits[(int64_t)gs * dec::kVocab + o] = __float2bfloat16(dl);
859	        }
860	        __syncthreads();
861	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j]  (head dX), feature-parallel → dh row rlast.
862	        // Then final-norm bwd of that single row → scratch.dh[rlast].
863	        // Use fnx cache (xhat) + fni (inv). Accumulate norm γ/β. (head dW is P2.)
864	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
865	            float dhn = 0.0f;
866	            for (int o = 0; o < dec::kVocab; ++o)
867	                dhn += lg[o] * w.out_w[(int64_t)o * dec::kD + j];
868	            // final-norm bwd needs the row-reduce of dxhat; stash dhn into work row rlast.
869	            sc.work[(int64_t)rlast * dec::kD + j] = dhn;
870	        }
871	        __syncthreads();
872	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only last pos contributes.)
873	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
874	            float dhn = sc.work[(int64_t)rlast * dec::kD + j];
875	            float xh = sc.fnx[(int64_t)rlast * dec::kD + j];
876	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
877	        }
878	        __syncthreads();
879	        // LN dx (single row): dxhat=dhn*norm_w; reduce; dh[rlast] = inv*(dxhat-(sda+xhat*sdax)/d).
880	        {
881	            const float* dyr = sc.work + (int64_t)rlast * dec::kD;
882	            const float* xhr = sc.fnx + (int64_t)rlast * dec::kD;
883	            float sda = 0.0f, sdax = 0.0f;
884	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
885	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
886	            }
887	            sda = dec_block_sum(sda, red); sdax = dec_block_sum(sdax, red);
888	            float iv = sc.fni[rlast];
889	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
890	                float dxhat = dyr[j] * w.norm_w[j];
891	                sc.dh[(int64_t)rlast * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
892	            }
893	            __syncthreads();
894	        }
895	    }
896	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only last positions nonzero).
897	
898	    // ── per-layer backward (reverse). dh is the running adjoint (grad wrt the
899	    //    layer's n2 output). All fwd intermediates are in scratch/DecActs (NO
900	    //    recompute). ──
