935	        // SAVE the residual dr1 into sc.dh NOW (dh is free — its grad was consumed into
936	        // dr2 at the top of this layer); attention bwd will overwrite work2. Then add the
937	        // in_proj dX path to it. da → dY_a acts (bf16, out_proj dW operand).
938	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
939	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1  (saved across attn bwd)
940	            acts.dY_a[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
941	        }
942	        __syncthreads();
943	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
944	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * dec::kD, L.out_w,
945	                                           sc.work, dec::kD, dec::kD, sA, sB);  // dctx
946	        __syncthreads();
947	        // attention bwd: (qkv[li], attn[li], dctx=work) → dqkv [nrows,3d] fp32 into
948	        //   work2 (3d=384 ≤ dff=512, fits). Then → dY_qkv acts (bf16, in_proj dW operand).
949	        dectc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
950	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x)
951	            acts.dY_qkv[li][(int64_t)g0 * 3 * dec::kD + idx] = __float2bfloat16(work2[idx]);
