1032	            sm->adj_c[s][c] = sm->adj_a[s][c] * mb_silu_grad(a->conv[s][c]);   // dconv
1033	        }
1034	        __syncthreads();
1035	        //   conv bwd: dx -> adj_a (dx_main_raw); reads dconv=adj_c, in=x_main_raw.
1036	        mb_conv1d_bwd(&sm->adj_c[0][0], &a->x_main_raw[0][0], L.conv_w,
1037	                      G.conv_w, G.conv_b, &sm->adj_a[0][0]);   // adj_a := dx_main_raw
1038	        // (12) dxz = cat[dx_main_raw, dz] (adj_a | adj_b). in_proj bwd: dW_in +=
1039	        //   dxz^T @ hin ; dx_inproj = dxz @ in_w.  in_w is [2*d_inner, d]; rows
1040	        //   [0,d_inner) pair with x_main_raw, [d_inner,2di) with z.
1041	        //   dx (=dx_inproj + dx_residual) goes to the previous layer's dh.
1042	        {
1043	            // dW_in: rows 0..d_inner-1 from dx_main_raw(adj_a), d_inner..2di-1 from dz(adj_b).
1044	            const int half = mb::kDInner;
1045	            for (int o = threadIdx.x; o < 2 * mb::kDInner; o += blockDim.x) {
1046	                const float* dyo = (o < half) ? &sm->adj_a[0][0] : &sm->adj_b[0][0];
1047	                const int oo = (o < half) ? o : (o - half);
1048	                for (int i = 0; i < mb::kD; ++i) {
1049	                    float acc = 0.0f;
1050	                    #pragma unroll
1051	                    for (int s = 0; s < mb::kSeq; ++s)
1052	                        acc += dyo[s * mb::kDInner + oo] * hin[s * mb::kD + i];
1053	                    G.in_w[(int64_t)o * mb::kD + i] += acc;
